// PR 1525 evidence: exercise the overhauled Roam settings panel and screenshot each surface.
import path from "node:path";

const SHOT = async (page, outDir, name) =>
  page.screenshot({ path: path.join(outDir, `${name}.png`), fullPage: false });

const openSettings = async (page) => {
  await page.keyboard.press("Escape").catch(() => {});
  await page.evaluate(() => {
    window.roamAlphaAPI.ui.commandPalette?.open?.();
  });
  await page.waitForTimeout(500);
  await page.keyboard.type("Discourse Graph Settings", { delay: 15 });
  await page.waitForTimeout(800);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(1500);
};

const dialog = (page) => page.locator(".bp3-dialog, .bp3-overlay .bp3-card").first();

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder));
  },

  async run({ page, outDir }) {
    const proof = {};

    await openSettings(page);
    const panel = dialog(page);
    await panel.waitFor({ timeout: 20000 });
    await SHOT(page, outDir, "01-settings-landing");

    // Build-identity guard: the loaded build must be this branch's, not another session's.
    proof.versionStamp = await panel.innerText().then((t) => {
      const m = t.match(/v?\d+\.\d+\.\d+[^\s]*/);
      return m ? m[0] : null;
    });

    // The four topic sections replace the Personal/Global split.
    const navText = await panel.innerText();
    proof.sectionsPresent = ["Preferences", "Features", "Grammar", "Advanced"].filter(
      (s) => navText.includes(s),
    );
    proof.oldSplitGone =
      !navText.includes("Personal Settings") && !navText.includes("Global Settings");

    for (const section of ["Preferences", "Features", "Grammar", "Advanced"]) {
      const tab = panel.getByText(section, { exact: true }).first();
      if (await tab.count()) {
        await tab.click();
        await page.waitForTimeout(900);
        await SHOT(page, outDir, `02-section-${section.toLowerCase()}`);
      }
    }

    // Grammar > Nodes drill-down.
    await panel.getByText("Grammar", { exact: true }).first().click();
    await page.waitForTimeout(700);
    const nodesEntry = panel.getByText("Nodes", { exact: true }).first();
    if (await nodesEntry.count()) {
      await nodesEntry.click();
      await page.waitForTimeout(900);
      await SHOT(page, outDir, "03-grammar-nodes");
      const firstNode = panel.locator("[data-setting-anchor], .bp3-menu-item, a").nth(0);
      if (await firstNode.count()) {
        await firstNode.click();
        await page.waitForTimeout(1000);
        await SHOT(page, outDir, "04-node-drilldown");
        proof.nodeDrilldownOpened = true;
      }
    }

    // Settings search.
    const search = panel.locator("input[type='search'], input[placeholder*='earch']").first();
    if (await search.count()) {
      await search.click();
      await search.fill("overlay");
      await page.waitForTimeout(1000);
      await SHOT(page, outDir, "05-search-overlay");
      proof.searchResultsText = (await panel.innerText()).slice(0, 400);
      await search.fill("");
      await page.waitForTimeout(500);
    } else {
      proof.searchResultsText = "search input not found";
    }

    proof.screenshots = [
      "01-settings-landing",
      "02-section-*",
      "03-grammar-nodes",
      "04-node-drilldown",
      "05-search-overlay",
    ];
    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

