// PR 1525 evidence: exercise the overhauled Roam DG settings panel and screenshot each surface.
import path from "node:path";

const SHOT = (page, outDir, name) =>
  page.screenshot({ path: path.join(outDir, `${name}.png`) });

const runCommand = async (page, command) => {
  await page.keyboard.press("Escape").catch(() => {});
  await page.waitForTimeout(300);
  await page.click("body", { position: { x: 700, y: 400 } }).catch(() => {});
  await page.keyboard.press("Meta+p");
  await page.waitForTimeout(600);
  await page.keyboard.type(command, { delay: 20 });
  await page.waitForTimeout(900);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(1800);
};

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder));
  },

  async run({ page, outDir }) {
    const proof = { steps: [] };

    await runCommand(page, "DG: Open - Discourse settings");
    const panel = page.locator(".dg-settings-tabs").first();
    await panel.waitFor({ timeout: 25000 });
    await page.waitForTimeout(700);
    await SHOT(page, outDir, "01-settings-landing");
    proof.steps.push("settings panel opened");

    const navText = await panel.innerText();
    proof.sectionsPresent = ["Preferences", "Features", "Grammar", "Advanced"].filter((s) =>
      navText.includes(s),
    );
    proof.oldSplitGone =
      !navText.includes("Personal Settings") && !navText.includes("Global Settings");

    // Each of the four topic sections.
    for (const section of ["Preferences", "Features", "Grammar", "Advanced"]) {
      const tab = panel.getByText(section, { exact: true }).first();
      if (await tab.count()) {
        await tab.click({ timeout: 8000 }).catch(() => {});
        await page.waitForTimeout(1100);
        await SHOT(page, outDir, `02-section-${section.toLowerCase()}`);
        proof.steps.push(`section ${section}`);
      }
    }

    // Grammar > Nodes drill-down.
    const grammar = panel.getByText("Grammar", { exact: true }).first();
    if (await grammar.count()) {
      await grammar.click().catch(() => {});
      await page.waitForTimeout(800);
    }
    const nodes = panel.getByText("Nodes", { exact: true }).first();
    if (await nodes.count()) {
      await nodes.click().catch(() => {});
      await page.waitForTimeout(1200);
      await SHOT(page, outDir, "03-grammar-nodes");
      proof.steps.push("grammar > nodes");
      const nodeLink = panel.locator("a, .bp3-menu-item, [role='button']").filter({
        hasText: /^(Question|Claim|Evidence|Source|Hypothesis|Result|Issue)/,
      });
      if (await nodeLink.count()) {
        await nodeLink.first().click().catch(() => {});
        await page.waitForTimeout(1400);
        await SHOT(page, outDir, "04-node-drilldown");
        proof.nodeDrilldownText = (await panel.innerText()).slice(0, 300);
        proof.steps.push("node drill-down");
      }
    }

    // Settings search.
    const search = page
      .locator(".bp3-dialog input[placeholder*='earch'], .bp3-dialog input[type='search']")
      .first();
    if (await search.count()) {
      await search.click().catch(() => {});
      await search.fill("overlay");
      await page.waitForTimeout(1200);
      await SHOT(page, outDir, "05-search-overlay");
      proof.searchText = (await panel.innerText()).slice(0, 400);
      proof.steps.push("search");
    } else {
      proof.searchText = "SEARCH INPUT NOT FOUND";
    }

    // Export dialog options styling (ENG-2185 + the pre-overhaul-style fix).
    await page.keyboard.press("Escape").catch(() => {});
    await page.waitForTimeout(700);
    await runCommand(page, "Export Discourse Graph");
    await page.waitForTimeout(1500);
    await SHOT(page, outDir, "06-export-dialog");
    const exportDialog = page.locator(".bp3-dialog").first();
    if (await exportDialog.count()) {
      proof.exportDialogText = (await exportDialog.innerText()).slice(0, 400);
      const toggle = exportDialog.getByText(/option/i).first();
      if (await toggle.count()) {
        await toggle.click().catch(() => {});
        await page.waitForTimeout(1000);
        await SHOT(page, outDir, "07-export-options");
        proof.exportOptionsSwitches = await exportDialog.locator(".bp3-switch").count();
        proof.exportOptionsCheckboxes = await exportDialog.locator(".bp3-checkbox").count();
        proof.steps.push("export options");
      }
    }

    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

// PR 1525 evidence: walk every leaf page of the overhauled Roam DG settings panel.
import path from "node:path";

const SHOT = (page, outDir, name) =>
  page.screenshot({ path: path.join(outDir, `${name}.png`) });

const runCommand = async (page, command) => {
  await page.keyboard.press("Escape").catch(() => {});
  await page.waitForTimeout(300);
  await page.click("body", { position: { x: 700, y: 400 } }).catch(() => {});
  await page.keyboard.press("Meta+p");
  await page.waitForTimeout(600);
  await page.keyboard.type(command, { delay: 20 });
  await page.waitForTimeout(900);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(1800);
};

// Leaf nav items only: the bold group names are headings, not tabs.
const LEAVES = [
  ["General", "preferences-general"],
  ["Styling", "preferences-styling"],
  ["Discourse context", "features-discourse-context"],
  ["Canvas", "features-canvas"],
  ["Left sidebar", "features-left-sidebar"],
  ["Nodes", "grammar-nodes"],
  ["Relations", "grammar-relations"],
  ["Queries", "advanced-queries"],
];

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder));
  },

  async run({ page, outDir }) {
    const proof = { leaves: {}, issues: [] };

    await runCommand(page, "DG: Open - Discourse settings");
    const panel = page.locator(".dg-settings-tabs").first();
    await panel.waitFor({ timeout: 25000 });
    await page.waitForTimeout(800);

    const navText = await panel.innerText();
    proof.sectionsPresent = ["Preferences", "Features", "Grammar", "Advanced"].filter((s) =>
      navText.includes(s),
    );
    proof.oldSplitGone =
      !navText.includes("Personal Settings") && !navText.includes("Global Settings");
    proof.buildStamp = await panel
      .locator("text=/v\\d+\\.\\d+\\.\\d+/")
      .first()
      .innerText()
      .catch(() => null);

    for (const [label, slug] of LEAVES) {
      const item = panel.getByText(label, { exact: true }).first();
      if (!(await item.count())) {
        proof.issues.push(`nav item missing: ${label}`);
        continue;
      }
      await item.click({ timeout: 8000 }).catch(() => {});
      await page.waitForTimeout(1200);
      await SHOT(page, outDir, `leaf-${slug}`);
      const body = await panel.innerText();
      // Strip the nav column so the record reflects the page body.
      proof.leaves[label] = body.slice(body.indexOf("Queries") + 7, body.indexOf("Queries") + 400);
    }

    // Grammar > Nodes drill-down: the table's edit (pencil) action opens a node page.
    await panel.getByText("Nodes", { exact: true }).first().click().catch(() => {});
    await page.waitForTimeout(1000);
    const editIcons = panel.locator("[icon='edit'], .bp3-icon-edit").first();
    if (await editIcons.count()) {
      await editIcons.click().catch(() => {});
      await page.waitForTimeout(1500);
      await SHOT(page, outDir, "node-drilldown");
      proof.nodeDrilldown = (await panel.innerText()).slice(0, 500);
    } else {
      proof.issues.push("node drill-down: no edit icon found");
    }

    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

