// PR 1525: both halves of the split 720px cap must still apply after the :has() rule split.
import path from "node:path";

const SHOT = (page, outDir, name) =>
  page.screenshot({ path: path.join(outDir, `${name}.png`) });

const runCommand = async (page, command) => {
  await page.keyboard.press("Escape").catch(() => {});
  await page.waitForTimeout(300);
  await page.click("body", { position: { x: 700, y: 400 } }).catch(() => {});
  await page.keyboard.press("Meta+p");
  await page.waitForTimeout(600);
  await page.keyboard.type(command, { delay: 20 });
  await page.waitForTimeout(900);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(1800);
};

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder));
  },

  async run({ page, outDir }) {
    const proof = {};

    await runCommand(page, "DG: Open - Discourse settings");
    const panel = page.locator(".dg-settings-tabs").first();
    await panel.waitFor({ timeout: 25000 });
    await page.waitForTimeout(900);

    // Half 1: the plain selector.
    proof.rowPanelCap = await page.evaluate(() => {
      const el = document.querySelector(".dg-settings-row-panel > *");
      return el ? getComputedStyle(el).maxWidth : "NO ELEMENT";
    });
    await SHOT(page, outDir, "width-01-row-panel");

    // Half 2: the :has() selector, on the node config page.
    await panel.getByText("Nodes", { exact: true }).first().click().catch(() => {});
    await page.waitForTimeout(1000);
    const edit = panel.locator("[icon='edit'], .bp3-icon-edit").first();
    if (await edit.count()) {
      await edit.click().catch(() => {});
      await page.waitForTimeout(1500);
    }
    proof.nodeConfigCaps = await page.evaluate(() => {
      const kids = Array.from(document.querySelectorAll(".dg-settings-node-config > *"));
      return kids.slice(0, 8).map((el) => ({
        hasSpec: Boolean(el.querySelector(".roamjs-node-specification")),
        maxWidth: getComputedStyle(el).maxWidth,
      }));
    });
    await SHOT(page, outDir, "width-02-node-config");

    proof.hasSupported = await page.evaluate(() =>
      CSS.supports("selector(:has(*))"),
    );
    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

